}"

"query callfundingeligibility(
  $clientId: String,
  $currency: SupportedCountryCurrencies,
  $merchantId: [String],
) {
  fundingEligibility(
    clientId: $clientId,
    currency: $currency,
    merchantId: $merchantId,
  ) {
    paypal {
      eligible
      reasons
    }
    credit {
      eligible
      reasons
    }
    paylater {
      eligible
      reasons
    }
  }
}"

"mutation UPGRADE_LOW_SCOPED_ACCESS_TOKEN(
  $token: String!
