}"

"mutation THREEDS_CREATE_CONFIRMATION(
  $bypassConfirmationProcess: Boolean,
  $confirmationMethod: ThreedsConfirmationMethod!,
  $cvv: String,
  $fiID: String,
  $referenceId: String,
  $senderContext: ThreedsSenderContextInput!
) {
  threedsCreateConfirmation(
    bypassConfirmationProcess: $bypassConfirmationProcess,
    confirmationMethod: $confirmationMethod,
    cvv: $cvv,
    fiId:$fiID,
    referenceId: $referenceId,
    senderContext: $senderContext
  ) {
    brand
    confirmationId
    confirmationMethod
    payload
    redirectUrl {
      href
    }
    referenceId
    status
    stepUpUrl {
      href
    }
    transactionId
    version
  }
}"

